<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require_once 'includes/make_mailer.php'; require_admin($pdo);
$messages=[];
function clean_announcement_html(string $html): string {
    $dom=new DOMDocument('1.0','UTF-8'); @$dom->loadHTML('<?xml encoding="utf-8" ?><div>'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);
    $allowed=['div','p','br','strong','b','em','i','u','ul','ol','li','a','h2','h3','blockquote'];
    $walk=function(DOMNode $node) use (&$walk,$allowed): void { for($child=$node->firstChild;$child;){$next=$child->nextSibling;if($child instanceof DOMElement){if(!in_array(strtolower($child->tagName),$allowed,true)){while($child->firstChild)$node->insertBefore($child->firstChild,$child);$node->removeChild($child);}else{foreach(iterator_to_array($child->attributes) as $attr){if($child->tagName==='a'&&$attr->name==='href'&&preg_match('#^https?://#i',$attr->value))continue;$child->removeAttribute($attr->name);}if($child->tagName==='a')$child->setAttribute('rel','noopener noreferrer');$walk($child);}}elseif(!($child instanceof DOMText)&&!($child instanceof DOMComment))$node->removeChild($child);$child=$next;} };
    $root=$dom->getElementsByTagName('div')->item(0);if(!$root)return ''; $walk($root);$out='';foreach($root->childNodes as $child)$out.=$dom->saveHTML($child);return $out;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['csrf']??null))$messages[]=['kind'=>'danger','text'=>'Session expired. Refresh and try again.'];
 else{$subject=trim((string)($_POST['subject']??''));$html=clean_announcement_html((string)($_POST['body_html']??''));$text=trim(html_entity_decode(strip_tags(str_replace(['</p>','</div>','</li>','<br>','<br/>','<br />'],"\n",$html)),ENT_QUOTES|ENT_HTML5,'UTF-8'));
  if($subject===''||mb_strlen($subject)>180||$text===''||!array_intersect((array)($_POST['recipients']??[]),['team','subscribers']))$messages[]=['kind'=>'danger','text'=>'Enter a subject and announcement content, then select at least one recipient group.'];
  else{$targets=array_values(array_intersect((array)($_POST['recipients']??[]),['team','subscribers']));$recipients=[];if(in_array('subscribers',$targets,true))$recipients=array_merge($recipients,$pdo->query('SELECT email_addr FROM email_subscriptions WHERE unsubscribed_at IS NULL ORDER BY subscription_id')->fetchAll(PDO::FETCH_COLUMN));if(in_array('team',$targets,true))$recipients=array_merge($recipients,$pdo->query("SELECT email_addr FROM user_credentials WHERE role IN ('staff','admin') AND is_active=1 AND email_addr IS NOT NULL AND email_addr<>''")->fetchAll(PDO::FETCH_COLUMN));$recipients=array_values(array_unique($recipients));$sent=0;$failed=0;foreach($recipients as $recipient){try{if(send_notification_email((string)$recipient,$subject,$text,'announcement',$html))$sent++;else $failed++;}catch(Throwable $e){$failed++;error_log('Nomcha announcement failed: '.$e->getMessage());}}$messages[]=['kind'=>$failed?'warning':'success','text'=>"Announcement sent to {$sent} recipient(s).".($failed?" {$failed} could not be sent.":'')];}
 }
}
$pageTitle='Announcements';require 'includes/header.php';render_toasts($messages);
?>
<main class="container py-5"><div class="mb-4"><p class="text-uppercase small fw-semibold text-secondary mb-1">Admin only</p><h1>Announcements</h1><p class="text-secondary">Create a formatted email for your selected audiences.</p></div><form method="post" class="card card-body" id="announcement-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label" for="subject">Email subject</label><input class="form-control" id="subject" name="subject" maxlength="180" required></div><div class="row g-4"><div class="col-lg-8"><label class="form-label" for="mail-editor">Email content</label><div class="d-flex justify-content-between align-items-center mb-2"><div class="btn-toolbar gap-1" role="toolbar"><button type="button" class="btn btn-sm btn-outline-secondary" data-command="bold"><strong>B</strong></button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="italic"><em>I</em></button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="underline"><u>U</u></button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="insertUnorderedList">Bullets</button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="formatBlock" data-value="h2">Heading</button><button type="button" class="btn btn-sm btn-outline-secondary" data-link>Link</button></div><label class="form-check"><input class="form-check-input" type="checkbox" id="raw-mode"><span class="form-check-label">Raw HTML</span></label></div><div class="form-control" id="mail-editor" contenteditable="true" role="textbox" aria-multiline="true" style="min-height:260px;overflow:auto"><p></p></div><textarea class="form-control font-monospace" id="raw-editor" hidden rows="12"></textarea><input type="hidden" name="body_html" id="body-html"><p class="form-text mt-2">HTML is sanitized before sending. Each email includes an unsubscribe link.</p></div><aside class="col-lg-4"><section class="border rounded p-3"><h2 class="h6">Recipients</h2><label class="form-check"><input class="form-check-input" type="checkbox" name="recipients[]" value="team"><span class="form-check-label">Team</span></label><label class="form-check"><input class="form-check-input" type="checkbox" name="recipients[]" value="subscribers" checked><span class="form-check-label">Subscribers</span></label></section></aside></div><button class="btn btn-auth align-self-start mt-3" type="submit">Send announcement</button></form></main><script>(()=>{const form=document.getElementById('announcement-form'),editor=document.getElementById('mail-editor'),raw=document.getElementById('raw-editor'),toggle=document.getElementById('raw-mode');let useRaw=false;toggle.addEventListener('change',()=>{if(toggle.checked){raw.value=editor.innerHTML;editor.hidden=true;raw.hidden=false;useRaw=true}else{editor.innerHTML=raw.value;raw.hidden=true;editor.hidden=false;useRaw=false}});document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('mousedown',e=>e.preventDefault()));document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{editor.focus();document.execCommand(b.dataset.command,false,b.dataset.value||null)}));document.querySelector('[data-link]').addEventListener('click',()=>{const url=prompt('Enter a full https:// link');if(url&&/^https?:\/\//i.test(url)){editor.focus();document.execCommand('createLink',false,url)}});form.addEventListener('submit',()=>document.getElementById('body-html').value=useRaw?raw.value:editor.innerHTML)})();</script><?php require 'includes/footer.php'; ?>
